EXTRA['glossaire'] = [
  ['Accessibilité (a11y)', "Fait de rendre un site utilisable par tous, y compris les personnes en situation de handicap. « a11y » : a + 11 lettres + y."],
  ['Attribut', "Information ajoutée dans une balise ouvrante : href, alt, class, id, data-*…"],
  ['ARIA', "Accessible Rich Internet Applications : attributs (aria-label, aria-live…) qui complètent la sémantique HTML pour les technologies d'assistance."],
  ['Asynchrone', "Opération dont le résultat arrive plus tard sans bloquer le reste du programme (promesse, async/await)."],
  ['Blob', "« Binary Large Object » : un fichier en mémoire (image, JSON exporté). Un File est un Blob."],
  ['Box model', "Modèle de boîte CSS : content, padding, border, margin."],
  ['Cascade', "Règles qui décident quelle déclaration CSS s'applique quand plusieurs se contredisent (importance, spécificité, ordre)."],
  ['CCP', "Certificat de compétences professionnelles : bloc d'un titre professionnel (le DWWM en a deux)."],
  ['Centimes', "Unité utilisée par Ondea pour stocker l'argent en entiers et éviter les erreurs d'arrondi."],
  ['Classe CSS', "Nom donné via class=\"…\" et ciblé en CSS par .nom ; réutilisable sur plusieurs éléments."],
  ['Console', "Outil de développement (F12) qui affiche les messages console.log et les erreurs JavaScript."],
  ['Contraste', "Rapport de luminosité entre texte et fond. AA : 4,5:1 ; AAA : 7:1."],
  ['CRUD', "Create, Read, Update, Delete : les quatre opérations de base sur des données."],
  ['Délégation d\'événements', "Un seul écouteur sur un parent pour gérer les événements de tous ses enfants."],
  ['DOM', "Document Object Model : arbre d'objets représentant la page, manipulable en JavaScript."],
  ['Échappement', "Remplacement des caractères spéciaux (< > & \" ') par des entités pour qu'ils soient affichés et non interprétés."],
  ['Élément', "Balise ouvrante + contenu + balise fermante (ou élément vide)."],
  ['Espace de noms', "Objet global unique (window.OC) qui regroupe tout le code d'une application pour éviter les conflits de noms."],
  ['Événement', "Action détectée par le navigateur (click, input, submit, keydown…) à laquelle on réagit avec addEventListener."],
  ['Flexbox', "Modèle de mise en page CSS sur un axe (ligne ou colonne)."],
  ['Focus', "Élément actuellement actif au clavier ; doit toujours être visible."],
  ['Fonction fléchée', "Syntaxe courte d'une fonction : (a, b) => a + b."],
  ['Grid', "Modèle de mise en page CSS en deux dimensions (lignes et colonnes)."],
  ['Hash (#)', "Partie de l'URL après #, utilisée par les routeurs d'applications d'une seule page ; sa modification déclenche hashchange."],
  ['Hachage', "Transformation irréversible d'un mot de passe en empreinte (SHA-256…), salée pour éviter les attaques par dictionnaire."],
  ['IIFE', "Immediately Invoked Function Expression : fonction exécutée dès sa définition pour créer une portée privée."],
  ['Index (IndexedDB)', "Structure qui permet de rechercher rapidement des objets par une propriété autre que la clé."],
  ['IndexedDB', "Base de données NoSQL intégrée au navigateur : objets, fichiers, transactions, index."],
  ['JSON', "JavaScript Object Notation : format texte d'échange de données ; JSON.stringify / JSON.parse."],
  ['Landmark', "Zone repère d'une page (header, nav, main, aside, footer) permettant une navigation rapide."],
  ['LocalStorage', "Stockage clé/valeur persistant du navigateur, limité à quelques Mo de texte."],
  ['Media query', "Règle CSS conditionnelle (@media (min-width: 900px)) selon l'écran ou les préférences."],
  ['Mobile first', "Méthode qui écrit d'abord le CSS du petit écran puis l'enrichit pour les écrans plus larges."],
  ['Object store', "Équivalent d'une table dans IndexedDB."],
  ['Portée (scope)', "Zone du code où une variable existe (bloc, fonction, globale)."],
  ['prefers-reduced-motion', "Préférence système indiquant que l'utilisateur souhaite moins d'animations."],
  ['Promesse', "Objet représentant un résultat futur : en attente, tenue ou rompue."],
  ['Responsive', "Capacité d'une interface à s'adapter à toutes les tailles d'écran."],
  ['SPA', "Single Page Application : application d'une seule page HTML dont le contenu change sans rechargement."],
  ['Sélecteur', "Partie d'une règle CSS qui désigne les éléments ciblés."],
  ['Sémantique', "Utilisation des balises HTML selon leur sens et non leur apparence."],
  ['Spécificité', "Poids d'un sélecteur CSS : id > classe/attribut/pseudo-classe > élément."],
  ['Template literal', "Chaîne entre accents graves `…` qui accepte ${expressions} et les retours à la ligne."],
  ['Transaction', "Groupe d'opérations de base de données qui réussissent toutes ou sont toutes annulées."],
  ['TVA / HT / TTC', "Hors taxes + taxe sur la valeur ajoutée = toutes taxes comprises. TTC = HT × (1 + taux)."],
  ['Variable CSS', "Propriété personnalisée (--nom) lue avec var(--nom) ; base des thèmes."],
  ['Viewport', "Zone d'affichage du navigateur ; la balise meta viewport adapte la page aux mobiles."],
  ['WCAG', "Web Content Accessibility Guidelines : règles internationales d'accessibilité (niveaux A, AA, AAA)."],
  ['XSS', "Cross-Site Scripting : faille d'injection de code dans la page via une donnée non échappée."]
]

